UPDATE "lessons" AS l SET "summary" = 'Write your first web page with headings, text, links and images.', "body" = 'HTML uses **tags** in angle brackets to mark up content. Most tags come in pairs: an opening tag and a closing tag with a slash.

### Your first page
Create a file called `index.html` and type:

```
<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8">
    <title>Mary''s Tailoring</title>
  </head>
  <body>
    <h1>Mary''s Tailoring</h1>
    <p>School uniforms and dresses in Paynesville.</p>
    <a href="tel:+231000000000">Call us</a>
  </body>
</html>
```

Open the file in your browser to see it.

### Common tags
- `<h1>` to `<h6>`: headings, from most to least important
- `<p>`: a paragraph
- `<a href="…">`: a link
- `<img src="photo.jpg" alt="…">`: an image. The **alt** text describes it for people who cannot see it
- `<ul>` and `<li>`: a bulleted list

### Good habits
Use one `<h1>` per page, keep headings in order, and always write alt text.

Draft lesson: to be checked by a JesTech subject reviewer before launch.', "checklist" = '["Create index.html with a heading and paragraph","Add a link and an image with alt text","Open the page in your browser"]'::jsonb, "est_minutes" = 12
FROM "course_modules" AS m, "courses" AS c WHERE l."module_id" = m."id" AND m."course_id" = c."id" AND c."slug" = 'web-development-fundamentals' AND l."slug" = 'html-structure' AND l."body" LIKE 'This lesson introduces %';
--> statement-breakpoint
UPDATE "lessons" AS l SET "summary" = 'Add colour, fonts and spacing with CSS.', "body" = 'CSS describes how HTML should look. A CSS **rule** has a **selector** (what to style) and **declarations** (how to style it).

```
h1 {
  color: #FF6D00;
  font-size: 32px;
}
p {
  line-height: 1.6;
}
```

### Connect your stylesheet
Save your CSS in `style.css` and link it inside `<head>`:

```
<link rel="stylesheet" href="style.css">
```

### The box model
Every element is a box:
- **content**: the text or image
- **padding**: space inside the box
- **border**: the edge
- **margin**: space outside the box

### Classes
Give elements a class to style them separately: `<p class="price">` and in CSS `.price { font-weight: bold; }`.

Draft lesson: to be checked by a JesTech subject reviewer before launch.', "checklist" = '["Create style.css and link it","Change a heading colour and font size","Use padding and margin on a box","Style an element with a class"]'::jsonb, "est_minutes" = 12
